window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-fa09f6d30d9a068e"]={"versions": [{"id": "FIG-fa09f6d30d9a068e", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Kommentar-/Notizdiagramm zur Illustration einer unvollständigen bzw. ungültigen Modellkonstellation im Kontext des AUTOSAR Generic Structure Template (GST), speziell hinsichtlich der Splitbarkeit von Modellelementen (<code>atpSplitable</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm enthält als einzige visuelle Entität ein rot hinterlegtes Notizsymbol mit abgeknickter Ecke. Es führt den Textinhalt <code>nonSplitDataSpec is missing here. It is not splitable.</code> und weist keine weiteren Komponenten, Instanzen oder Schnittstellenverbindungen auf.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Hinweisfeld ohne zeitliche Abläufe, Sequenzen, Nachrichtenaustausche oder dynamische Verhaltensweisen.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dient als deklarativer Fehlernachweis bzw. Negativbeispiel für ein unvollständiges Teilmodell (Invalid Partial Model). Zeigt an, dass ein nicht-splitbares Element (<code>nonSplitDataSpec</code>) an einer erforderlichen Stelle im Modell fehlt und das Modell daher syntaktisch bzw. semantisch unzulässig ist.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-869e161f66c22a9a", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzdiagramm) im Kontext des AUTOSAR Generic Structure Template (GST). Das Diagramm stellt ein unvollständiges bzw. ungültiges Teilmodell (Invalid Partial Model) dar und demonstriert die Modellierungshierarchie sowie die Restriktionen bezüglich der Splitbarkeit von Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist eine hierarchische Instanzenstruktur:</p>\n<ul class=\"fig-list\"><li><code>:Root</code>: Oberstes Wurzelelement.\n</li><li><code>package :Package</code>: Untergeordnet über eine mit dem Stereotyp <code>«atpSplitable»</code> annotierte Assoziation; besitzt das Attribut <code>shortName = Supplier</code>.\n</li><li><code>element :NotWithSplitable</code>: Untergeordnetes Element unterhalb des Packages (Assoziation annotiert mit <code>«atpSplitable»</code>); Attribute: <code>shortName = engine</code>, <code>a = theString</code>, <code>b = theString</code>.\n</li><li><code>element :WithSplitable</code>: Weiteres Element unterhalb des Packages (Assoziation annotiert mit <code>«atpSplitable»</code>); Attribute: <code>shortName = centralLock</code>, <code>a = aString</code>, <code>b = aString</code>.\n</li><li>Rote Notiz/Kommentarbox am unteren linken Rand mit dem Hinweis: <code>nonSplitDataSpec is missing here. It is not splitable.</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm ohne dynamische Sequenzabläufe oder Zustandsübergänge. Es beschreibt den statischen Instanzzustand eines unvollständigen AUTOSAR-Teilmodells.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht ein ungültiges Teilmodell gemäß AUTOSAR-Splitregeln: Während Assoziationen mit dem Stereotyp <code>«atpSplitable»</code> eine Aufteilung von Modellteilen erlauben, führt das Fehlen von nicht-splitbaren Kindelementen (hier <code>nonSplitDataSpec</code> unterhalb von <code>NotWithSplitable</code>) zu einer Verletzung der Modellkonsistenz. Für Werkzeugentwickler bedeutet dies, dass solche unvollständigen Teilmodelle von Validatoren als invalid zurückgewiesen werden müssen.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-835e88691ad9346d", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Objektdiagramm (Instanzdiagramm) im Kontext des AUTOSAR Generic Structure Template (GST). Das Diagramm stellt ein unvollständiges bzw. ungültiges Teilmodell (Invalid Partial Model) dar und demonstriert die Modellierungshierarchie sowie die Restriktionen bezüglich der Splitbarkeit von Modellelementen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt ist eine hierarchische Instanzenstruktur:</p>\n<ul class=\"fig-list\"><li><code>:Root</code>: Oberstes Wurzelelement.\n</li><li><code>package :Package</code>: Untergeordnet über eine mit dem Stereotyp <code>«atpSplitable»</code> annotierte Assoziation; besitzt das Attribut <code>shortName = Supplier</code>.\n</li><li><code>element :NotWithSplitable</code>: Untergeordnetes Element unterhalb des Packages (Assoziation annotiert mit <code>«atpSplitable»</code>); Attribute: <code>shortName = engine</code>, <code>a = theString</code>, <code>b = theString</code>.\n</li><li><code>element :WithSplitable</code>: Weiteres Element unterhalb des Packages (Assoziation annotiert mit <code>«atpSplitable»</code>); Attribute: <code>shortName = centralLock</code>, <code>a = aString</code>, <code>b = aString</code>.\n</li><li>Rote Notiz/Kommentarbox am unteren linken Rand mit dem Hinweis: <code>nonSplitDataSpec is missing here. It is not splitable.</code>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Objektdiagramm ohne dynamische Sequenzabläufe oder Zustandsübergänge. Es beschreibt den statischen Instanzzustand eines unvollständigen AUTOSAR-Teilmodells.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht ein ungültiges Teilmodell gemäß AUTOSAR-Splitregeln: Während Assoziationen mit dem Stereotyp <code>«atpSplitable»</code> eine Aufteilung von Modellteilen erlauben, führt das Fehlen von nicht-splitbaren Kindelementen (hier <code>nonSplitDataSpec</code> unterhalb von <code>NotWithSplitable</code>) zu einer Verletzung der Modellkonsistenz. Für Werkzeugentwickler bedeutet dies, dass solche unvollständigen Teilmodelle von Validatoren als invalid zurückgewiesen werden müssen.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-fa09f6d30d9a068e", "to": "FIG-869e161f66c22a9a", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Ergänzung der vollständigen AUTOSAR-Objektbaumstruktur mit den Instanzen <code>:Root</code>, <code>package :Package</code> (shortName = Supplier) sowie den untergeordneten Elementen <code>element :NotWithSplitable</code> (shortName = engine, a = theString, b = theString) und <code>element :WithSplitable</code> (shortName = centralLock, a = aString, b = aString).\n</li><li>Ergänzung der splitable-Beziehungen zwischen den Objekten, jeweils annotiert mit dem Stereotyp <code>«atpSplitable»</code>.\n</li><li>Die zuvor isolierte Fehlermeldung/Kommentarnotiz („nonSplitDataSpec is missing here. It is not splitable.“) ist nun als referenzierender Hinweis unterhalb der Modellelemente platziert.\n</li></ul>"}, {"from": "FIG-869e161f66c22a9a", "to": "FIG-835e88691ad9346d", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
